import json
from hypothesis import strategies as st

MOD = 10**9 + 7

@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    mode = draw(st.integers(0, 3))
    if mode == 0:
        nums = draw(st.lists(st.integers(1, 10), min_size=n, max_size=n))
    elif mode == 1:
        v = draw(st.integers(1, 10**9))
        nums = [v] * n
    elif mode == 2:
        nums = draw(st.lists(st.sampled_from([1, 2, 10**9]), min_size=n, max_size=n))
    else:
        nums = sorted(draw(st.lists(st.integers(1, 10**9), min_size=n, max_size=n)))
        if draw(st.booleans()):
            nums = nums[::-1]
    return json.dumps(nums)

def validate(inp):
    try:
        nums = json.loads(inp)
    except Exception:
        return False
    if not isinstance(nums, list):
        return False
    if not (1 <= len(nums) <= 10**5):
        return False
    for x in nums:
        if type(x) is not int or not (1 <= x <= 10**9):
            return False
    return True

def ref(inp):
    nums = json.loads(inp)
    n = len(nums)
    total = 0
    for mask in range(1, 1 << n):
        group = [nums[i] for i in range(n) if (mask >> i) & 1]
        total += max(group) ** 2 * min(group)
    return str(total % MOD)
